import { ShopifyStorefront } from '../lib/api/shopify-storefront';
import { CollectionService } from '../services/collection-service';
import { ProductRecommendationService } from '../services/recommended-product-service';

export class StorefrontFactory {
  constructor(config) {
    this.storefront = new ShopifyStorefront(config);
  }

  createCollectionService() {
    return new CollectionService(this.storefront);
  }

  createProductRecommendationService() {
    return new ProductRecommendationService(this.storefront);
  }
}
