import { StorefrontFactory } from '../factories/storefront-factory';
import { getLogger } from '~/lib/log';

const log = getLogger('base-listing');

export function storeKeys(config = {}) {
  return {
    loading: true,
    error: null,
    domain: config.domain || '',
    accessToken: config.accessToken || '',
    apiVersion: config.apiVersion || '2024-01',
    productsPerPage: config.productsPerPage || 12,

    createStorefrontFactory() {
      return new StorefrontFactory({
        domain: this.domain,
        accessToken: this.accessToken,
        apiVersion: this.apiVersion,
      });
    },
    handleError(error, context = 'Unknown') {
      this.error = error.message;
      log.error(`Error in ${context}:`, error);
    },
    setLoadingState(loading = true) {
      this.loading = loading;
      if (loading) {
        this.error = null;
      }
    },
  };
}
