export default function formatProductData(productNode) {
  if (!productNode) {
    return null;
  }

  const featuredImage = getFeaturedImage(productNode);
  const variants = getVariants(productNode);
  const { minPrice, maxPrice } = getPriceRange(variants, productNode);
  const currency = getCurrency(variants, productNode);

  return {
    id: productNode.id,
    title: productNode.title,
    handle: productNode.handle,
    availableForSale: productNode.availableForSale,
    description: productNode.descriptionHtml,
    image: featuredImage?.url || null,
    featuredImage,
    variants,
    minPrice,
    maxPrice,
    currency,
    comparePrice: productNode.comparePrice,
  };
}

function getFeaturedImage(node) {
  const img
    = node?.media?.edges?.[0]?.node?.image
    || node?.featuredImage
    || null;

  return img
    ? {
      url: img.url,
      altText: img.altText,
      width: img.width,
      height: img.height,
    }
    : null;
}

function getVariants(node) {
  const edges = node?.variants?.edges || [];

  return edges.map(({ node: v = {} }) => {
    const selectedOptions = (v.selectedOptions || []).map((o) => ({
      name: o.name,
      value: o.value,
    }));

    const optionsMap = Object.fromEntries(
      selectedOptions.map((o) => [o.name, o.value]),
    );

    return {
      id: v.id,
      title: v.title || '',
      price: safeNumber(v.price?.amount),
      comparePrice: safeNumber(v.compareAtPrice?.amount),
      currency: v.price?.currencyCode || null,
      selectedOptions,
      options: optionsMap,
    };
  });
}

function getPriceRange(variants, node) {
  const variantPrices = variants
    .map((v) => v.price)
    .filter((p) => p !== null && !Number.isNaN(p));

  if (variantPrices.length) {
    return {
      minPrice: Math.min(...variantPrices),
      maxPrice: Math.max(...variantPrices),
    };
  }

  return {
    minPrice: safeNumber(node?.priceRange?.minVariantPrice?.amount),
    maxPrice: safeNumber(node?.priceRange?.maxVariantPrice?.amount),
  };
}

function getCurrency(variants, node) {
  return (
    variants[0]?.currency
    || node?.priceRange?.minVariantPrice?.currencyCode
    || null
  );
}

function safeNumber(value) {
  return value ? Number(value) : null;
}
