/* eslint-disable no-await-in-loop */

import { getLogger } from '~/lib/log';
const log = getLogger('GraphQLClient');

export class GraphQLClient {
  constructor({ endpoint, token, timeoutMs = 15000, maxRetries = 3 }) {
    this.endpoint = endpoint;
    this.token = token;
    this.timeoutMs = timeoutMs;
    this.maxRetries = maxRetries;
  }

  async fetch(query, variables = []) {
    let attempt = 0;
    while (true) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), this.timeoutMs);
      try {
        const response = await fetch(this.endpoint, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'X-Shopify-Storefront-Access-Token': this.token,
          },
          body: JSON.stringify({ query, variables }),
        });

        clearTimeout(timer);

        if (response.status === 429 && attempt < this.maxRetries) {
          const retryAfter
            = Number(response.headers.get('Retry-After')) * 1000
            || this._backoff(attempt);
          await this._delay(retryAfter);
          attempt++;
          continue;
        }

        const payload = await response.json().catch(() => ({}));
        const { data, errors } = payload || {};

        if (!response.ok || errors) {
          const message = errors
            ? errors.map(({ message }) => message).join(', ')
            : `HTTP ${response.status}`;

          if (attempt < this.maxRetries) {
            log.warn('Query failed, retrying', { message, attempt });

            await this._delay(this._backoff(attempt));
            attempt++;
            continue;
          }

          log.error('Query failed after retries', { message, attempt });
          return { ok: false, data: null, error: new Error(message) };
        }

        log.debug('Query successful', { dataKeys: Object.keys(data || {}) });
        return { ok: true, data, error: null };
      } catch (err) {
        clearTimeout(timer);
        if (attempt < this.maxRetries) {
          await this._delay(this._backoff(attempt));
          attempt++;
          continue;
        }

        log.error('Query failed after retries', {
          error: err.message,
          attempt,
        });
        return {
          ok: false,
          data: null,
          error: err instanceof Error ? err : new Error(String(err)),
        };
      }
    }
  }

  _backoff(attempt, base = 500) {
    return base * (2 ** Math.min(attempt, 6));
  }

  _delay(ms) {
    // eslint-disable-next-line
    return new Promise((resolve) => setTimeout(resolve, ms));
  }
}
